// run with: bare lib/node_modules/automap/automap.test.js
// 2 devices, sub() and batch() go through autobase, so what one device writes shows up on the other
const fs = require('bare-fs')
const os = require('bare-os')
const path = require('bare-path')
const Corestore = require('corestore')
const { create_automap } = require('./')

let failed = 0
module.exports = () => main().then(done) // the test of a module that uses this one runs it too
if (require.main === module) module.exports()

async function main () {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'automap-test-'))
  const store_a = new Corestore(path.join(root, 'a'))
  const store_b = new Corestore(path.join(root, 'b'))
  const a = create_automap({ store: store_a.namespace('vault-bee') })
  await a.ready()
  const b = create_automap({ store: store_b.namespace('vault-bee'), bootstrap: a.key })
  await b.ready()
  const streams = connect(store_a, store_b)
  await a.add_writer(b.base.local.key)
  await settle([a, b], () => b.writable)
  // batch
  const batch = a.batch()
  await batch.put('one', 1)
  await batch.put('two', 2)
  await batch.put('gone', 3)
  await batch.del('gone')
  check('nothing is written before flush', (await a.get('one')) === null)
  const length = a.base.local.length
  await batch.flush()
  check('a batch goes into autobase as one append', a.base.local.length === length + 4 && (await a.get('two'))?.value === 2, `${a.base.local.length - length} entries`)
  await settle([a, b], async () => (await b.get('two')) !== null)
  check('the batch reaches the other device, the del too', (await b.get('one'))?.value === 1 && (await b.get('two'))?.value === 2 && (await b.get('gone')) === null)
  // sub
  const settings = a.sub('settings')
  await settings.put('theme', 'dark')
  await a.put('theme', 'light')
  await settle([a, b], async () => (await b.sub('settings').get('theme')) !== null)
  check('a sub key reaches the other device and is read through its sub', (await b.sub('settings').get('theme'))?.value === 'dark')
  check('a sub key doesnt clash with the same key outside the sub', (await b.get('theme'))?.value === 'light')
  check('a sub key is stored with the same bytes as hyperbee\'s own sub (prefix + 0x00 + key)', (await b.get('settings\x00theme'))?.value === 'dark')
  // nested sub, a batch in a sub, and the other device writing into a sub
  await settings.sub('colors').put('main', 'blue')
  const sub_batch = settings.batch()
  await sub_batch.put('font', 'mono')
  await sub_batch.put('size', 13)
  await sub_batch.flush()
  await b.sub('settings').put('lang', 'en')
  await settle([a, b], async () => (await a.sub('settings').get('lang')) !== null && (await b.sub('settings').get('size')) !== null)
  check('a sub of a sub works like hyperbee\'s', (await b.sub('settings').sub('colors').get('main'))?.value === 'blue')
  check('a batch in a sub writes its keys into the sub', (await b.sub('settings').get('font'))?.value === 'mono' && (await b.sub('settings').get('size'))?.value === 13)
  check('the second device writes into a sub and the first one reads it', (await a.sub('settings').get('lang'))?.value === 'en')
  const keys = []
  for await (const { key } of b.sub('settings').create_read_stream()) keys.push(key)
  // like hyperbee, a sub lists its own keys and the keys of the subs inside it (colors\x00main)
  check('reading a sub only lists the keys under its prefix, like hyperbee', keys.join() === 'colors\x00main,font,lang,size,theme' && (await b.get('theme'))?.value === 'light', JSON.stringify(keys))
  streams.forEach(stream => stream.destroy())
  await a.close()
  await b.close()
}

function connect (store_a, store_b) {
  const stream_a = store_a.replicate(true)
  const stream_b = store_b.replicate(false)
  stream_a.pipe(stream_b).pipe(stream_a)
  return [stream_a, stream_b]
}

// update both devices until done() or about 15 seconds passed
async function settle (maps, done) {
  for (let i = 0; i < 150; i++) {
    for (const map of maps) await map.update()
    if (await done()) return
    await new Promise(resolve => setTimeout(resolve, 100))
  }
}

function check (name, ok, info = '') {
  if (!ok) failed++
  console.log(`${ok ? 'ok' : 'NOT ok'} ${name}${ok || info === '' ? '' : ` (${info})`}`)
}

function done () {
  console.log(failed ? `${failed} NOT ok` : 'all good')
  if (failed) throw new Error('automap tests failed')
}
